'use client';
import { renderMarkdown } from 'heavy-markdown';
import { formatDate } from 'big-date-lib';
import { useState } from 'react';

export function ProductPage({ product }: { product: Product }) {
  const [qty, setQty] = useState(1);
  return (
    <article>
      <h1>{product.name}</h1>
      <div dangerouslySetInnerHTML={{ __html: renderMarkdown(product.description) }} />
      <p>Updated {formatDate(product.updatedAt)}</p>
      <QtyStepper value={qty} onChange={setQty} />
      <AddToCart productId={product.id} qty={qty} />
    </article>
  );
}
